    concurrentUploadsTitle: 'Gelijktijdige uploads',
    concurrentUploadsDescription: 'Naar hoeveel printers de wachtrij tegelijk bestanden mag versturen. Printers ontvangen bestanden langzaam (een grote print kan enkele minuten duren), en elke printer wacht op zijn beurt — dus bij een grotere vloot voorkomt het verhogen hiervan dat de laatste printer in een batch elke overdracht moet uitzitten voordat hij aan de beurt is. Verlaag dit als je netwerk of Bambuddy-host moeite heeft met parallelle overdrachten.',
