    preheatDescription: 'Verwarm het bed (en de kamer, indien ondersteund) en houd op temperatuur voordat elke geplande print start. Handig voor technische filamenten (PA, ABS) op printers zonder actieve kamerverwarming — het bed verwarmt de kamer door straling tijdens de wachttijd. Het beddoel wordt uit het printbestand gelezen; kamergedrag hangt af van het printermodel.',
